package com.example.crm.customer;
import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/customers") public class CustomerController { private final CustomerService service; public CustomerController(CustomerService s){service=s;} record CustomerRequest(@NotBlank String name,String email,String phone){} @GetMapping public ResponseEntity<List<CustomerDto>> all(){return ResponseEntity.ok(service.findAll());} @GetMapping("/{id}") public ResponseEntity<CustomerDto> one(@PathVariable UUID id){try{return ResponseEntity.ok(service.find(id));}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} @PostMapping @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<CustomerDto> create(@Valid @RequestBody CustomerRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r.name(),r.email(),r.phone()));} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<CustomerDto> update(@PathVariable UUID id,@Valid @RequestBody CustomerRequest r){try{return ResponseEntity.ok(service.update(id,r.name(),r.email(),r.phone()));}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> delete(@PathVariable UUID id){try{service.delete(id);return ResponseEntity.noContent().build();}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} }
